// persona-card — tessera example web component (PersonaKit.PersonaCard).
//
// A Lit element over the contract mixin (CONTRACT.md §4). The generated
// wire contract (./persona_card.contract.generated.mjs) is regenerated by
// `mix compile` from the spec module — never edit it by hand.
//
// The click handler keeps an INTERNAL counter in a private field (not Lit
// reactive): it must survive every Hologram re-render, which is exactly
// what the e2e suite asserts.
import { LitElement, html, css } from "lit";
import { defineOnce, TesseraElement, emit } from "@noizu/tessera-core";
import contract from "./persona_card.contract.generated.mjs";

class PersonaCard extends TesseraElement(LitElement, contract) {
  static styles = css`
    :host {
      display: inline-block;
      border: 1px solid var(--persona-card-accent, #6366f1);
      border-radius: 8px;
      padding: 12px;
      margin: 4px;
      font-family: system-ui, sans-serif;
      background: #ffffff;
    }
    :host([disabled]) {
      opacity: 0.55;
    }
    .head {
      margin-bottom: 8px;
    }
    .name {
      font-weight: 700;
      margin-right: 8px;
    }
    .tagline {
      color: #475569;
      font-size: 0.9em;
    }
    .chips {
      margin: 6px 0;
    }
    .chip {
      display: inline-block;
      background: #eef2ff;
      color: #4338ca;
      border-radius: 999px;
      padding: 1px 8px;
      margin: 0 4px 4px 0;
      font-size: 0.8em;
    }
    button {
      cursor: pointer;
    }
    .internal {
      margin-left: 8px;
      color: #4f46e5;
      font-size: 0.85em;
    }
    footer {
      display: block;
      margin-top: 6px;
      color: #64748b;
    }
  `;

  // internal, non-reactive instance state — must NOT be reset by re-renders
  #internalClicks = 0;

  render() {
    const tags = Array.isArray(this.tagList) ? this.tagList : [];
    const disabled = this.disabled === true;

    return html`
      <div class="head">
        <span class="name" data-cy="persona-card-name">${this.displayName}</span>
        <span class="tagline">${this.tagline ?? ""}</span>
      </div>
      <div class="chips">
        ${tags.map((tag) => html`<span class="chip" data-cy="persona-card-chip">${tag}</span>`)}
      </div>
      <button
        id="select-btn"
        part="select-button"
        data-cy="persona-card-btn"
        ?disabled=${disabled}
        @click=${this.#onSelect}
      >
        select
      </button>
      <span class="internal" data-cy="persona-card-internal">internal:${this.#internalClicks}</span>
      <slot></slot>
      <footer><slot name="footer"></slot></footer>
    `;
  }

  #onSelect() {
    if (this.disabled === true) return;
    this.#internalClicks += 1;
    // Private fields are not reactive — refresh the visible counter.
    this.requestUpdate();
    // The contract event: composed + bubbling (CONTRACT.md §4), camelCase
    // detail keys — the bridge converts them to snake before dispatch.
    emit(this, "persona-select", {
      personaId: this.displayName,
      clickCount: this.#internalClicks,
    });
  }
}

export function register() {
  return defineOnce("persona-card", PersonaCard);
}

// LOAD-BEARING: this top-level register() call is what actually defines
// the custom element. Stateless SSR never calls init/3 — registration
// happens when the page bundle evaluates this module and reaches this
// statement (CONTRACT.md §3; `mix compile` warns if it is missing).
// Page bundles carry their own copy of this module — defineOnce makes the
// re-execution safe (CONTRACT.md §4).
register();
